import{_ as o,o as t,c as a,an as n}from"./chunks/framework.B97XrC3l.js";const u=JSON.parse('{"title":"Enzyme extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/enzyme.md","filePath":"extensions/enzyme.md","lastUpdated":null}'),r={name:"extensions/enzyme.md"};function s(i,e,c,d,l,m){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="extension-enzyme" tabindex="-1">Enzyme extension <a class="header-anchor" href="#extension-enzyme" aria-label="Permalink to &quot;Enzyme extension {#extension-enzyme}&quot;">​</a></h1><p><code>ComposableRecurrencesEnzymeExt</code> is loaded automatically when Enzyme is available alongside ComposableRecurrences.</p><p>It registers the <a href="/previews/PR615/explanation/adjoints-and-backends#adjoint-routing">rule</a> of every operator as an Enzyme reverse-mode rule.</p><p>On Julia 1.11, an operator built in code that Julia cannot infer can get a zero Enzyme reverse gradient for its scalar float fields, such as <code>b</code> in <code>Transform(+, b)</code> or the population of a <code>Depletion</code>. Uninferred code includes a closure that captures a variable it reassigns, or a call through a global that is not constant. Enzyme loses the gradient in that code, before any rule runs, so the extension cannot detect or refuse it. Instead it warns once per operator type, the first time Enzyme reverse mode differentiates an operator with an active scalar field on 1.11. Use Julia 1.12 or later, where Enzyme keeps these gradients, or build operators in type-stable code (check it with <code>@code_warntype</code>).</p><p>Under Enzyme reverse mode, a modifier whose type depends on a run-time branch, such as <code>m = flag ? Depletion(N) : Depletion(N, Floor())</code>, makes the call fail with <code>TypeError: in new, expected Tuple{...}, got a value of type Tuple{Base.RefValue{...}}</code>. The error comes from Enzyme when it differentiates the caller&#39;s keyword call <code>Recurrence(g; modifiers = (m,))</code>, before any package code runs. Call a function on each concrete modifier instead, such as <code>flag ? model(Depletion(N), θ) : model(Depletion(N, Floor()), θ)</code>, so that the operator is built from a value of one type.</p><p>Without runtime activity (<code>AutoEnzyme()</code>, or <code>Enzyme.Reverse</code> as given), Enzyme raises <code>EnzymeRuntimeActivityError</code> when an operator with an active part holds a constant array that lives outside the loss, such as a global population in <code>Depletion(PerStratum(N))</code>. Use <code>AutoEnzyme(; mode = Enzyme.set_runtime_activity(Enzyme.Reverse))</code>, as the tutorials do, or build every such array inside the loss, the kernel included.</p>',6)])])}const h=o(r,[["render",s]]);export{u as __pageData,h as default};
